package de.corporate.lc.check.domain;
import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.UUID;
@Entity @Table(name="document_check_decision",uniqueConstraints=@UniqueConstraint(columnNames={"lc_id","finding_code","document_name"})) public class DocumentCheckDecision{@Id private UUID id=UUID.randomUUID();@Column(name="lc_id",nullable=false)private UUID lcId;@Column(name="finding_code",nullable=false,length=100)private String findingCode;@Column(name="document_name",nullable=false)private String documentName="";@Column(nullable=false,length=30)private String decision;@Column(length=1000)private String comment;@Column(nullable=false,length=100)private String reviewedBy;@Column(nullable=false)private LocalDateTime reviewedAt=LocalDateTime.now();public UUID getId(){return id;}public UUID getLcId(){return lcId;}public void setLcId(UUID v){lcId=v;}public String getFindingCode(){return findingCode;}public void setFindingCode(String v){findingCode=v;}public String getDocumentName(){return documentName;}public void setDocumentName(String v){documentName=v==null?"":v;}public String getDecision(){return decision;}public void setDecision(String v){decision=v;}public String getComment(){return comment;}public void setComment(String v){comment=v;}public String getReviewedBy(){return reviewedBy;}public void setReviewedBy(String v){reviewedBy=v;}public LocalDateTime getReviewedAt(){return reviewedAt;}public void setReviewedAt(LocalDateTime v){reviewedAt=v;}}
